    """Build the valid height-one derivation of P -> P."""

    p = Atom("P")
    return {
        "root": Node((), Imp(p, p), ImpIntroRule(p, p, "leaf"), rank=1),
        "leaf": Node((p,), p, AssumptionRule(), rank=0),
    }


